252|impl GemmKernel for KernelFromPtx {
253|    fn matmul(
254|        &self,
255|        alpha: f32,
256|        a: &DeviceBuffer<f16>,
257|        b: &DeviceBuffer<f16>,
258|        beta: f32,
259|        c: &mut DeviceBuffer<f32>,
260|        m: usize,
261|        n: usize,
262|        k: usize,
263|    ) -> Result<(), GemmError> {
264|        // Validate dimensions
265|        if self.config.arch == GemmArch::Tcgen05 && !k.is_multiple_of(64) {
266|            return Err(GemmError::InvalidDimensions { m, n, k });
267|        }
268|
269|        // Check buffer sizes
270|        let a_expected = m * k;
271|        let b_expected = k * n;
272|        let c_expected = m * n;
273|
274|        if a.len() < a_expected {
275|            return Err(GemmError::BufferSizeMismatch {
276|                expected: a_expected,
277|                got: a.len(),
278|            });
279|        }
280|        if b.len() < b_expected {
281|            return Err(GemmError::BufferSizeMismatch {
282|                expected: b_expected,
283|                got: b.len(),
284|            });
285|        }
286|        if c.len() < c_expected {
287|            return Err(GemmError::BufferSizeMismatch {
288|                expected: c_expected,
289|                got: c.len(),
290|            });
291|        }
292|
293|        // If GPU is available, launch the kernel
294|        if self.gpu_available {
295|            if let (Some(ctx), Some(_module), Some(func), Some(stream)) =
296|                (&self.ctx, &self.module, &self.function, &self.stream)
297|            {
298|                // Bind context to thread
299|                ctx.bind_to_thread()
300|                    .map_err(|e| GemmError::LaunchFailed(e.to_string()))?;
301|
302|                // Convert device buffers to cuda-core format
303|                let dev_a = if a.is_backed() {
304|                    let buf = unsafe {
305|                        cuda_core::DeviceBuffer::from_raw_parts(
306|                            a.device_ptr() as cuda_core::sys::CUdeviceptr,
307|                            a.len(),
308|                            stream.context().clone(),
309|                        )
310|                    };
311|                    Arc::new(buf)
312|                } else {
313|                    let buf = cuda_core::DeviceBuffer::from_host(
314|                        stream,
315|                        a.as_slice().ok_or_else(|| GemmError::BufferSizeMismatch {
316|                            expected: a_expected,
317|                            got: 0,
318|                        })?,
319|                    )
320|                    .map_err(|e| GemmError::LaunchFailed(format!("H2D alloc failed: {e}")))?;
321|                    Arc::new(buf)
322|                };
323|
324|                let dev_b = if b.is_backed() {
325|                    let buf = unsafe {
326|                        cuda_core::DeviceBuffer::from_raw_parts(
327|                            b.device_ptr() as cuda_core::sys::CUdeviceptr,
328|                            b.len(),
329|                            stream.context().clone(),
330|                        )
331|                    };
332|                    Arc::new(buf)
333|                } else {
334|                    let buf = cuda_core::DeviceBuffer::from_host(
335|                        stream,
336|                        b.as_slice().ok_or_else(|| GemmError::BufferSizeMismatch {
337|                            expected: b_expected,
338|                            got: 0,
339|                        })?,
340|                    )
341|                    .map_err(|e| GemmError::LaunchFailed(format!("H2D alloc failed: {e}")))?;
342|                    Arc::new(buf)
343|                };
344|
345|                let mut dev_c = if c.is_backed() {
346|                    let buf = unsafe {
347|                        cuda_core::DeviceBuffer::from_raw_parts(
348|                            c.device_ptr() as cuda_core::sys::CUdeviceptr,
349|                            c.len(),
350|                            stream.context().clone(),
351|                        )
352|                    };
353|                    Arc::new(buf)
354|                } else {
355|                    let buf = cuda_core::DeviceBuffer::from_host(
356|                        stream,
357|                        c.as_mut_slice()
358|                            .ok_or_else(|| GemmError::BufferSizeMismatch {
359|                                expected: c_expected,
360|                                got: 0,
361|                            })?,
362|                    )
363|                    .map_err(|e| GemmError::LaunchFailed(format!("H2D alloc failed: {e}")))?;
364|                    Arc::new(buf)
365|                };
366|
367|                // Calculate grid/block dimensions
368|                let (grid_x, grid_y, block_size) = self.get_launch_config(m, n);
369|
370|                // Build kernel parameters (pointers to buffers)
371|                // Note: alpha/beta are passed as scalar values, not pointers
372|                let m_val = m as u32;
373|                let n_val = n as u32;
374|                let k_val = k as u32;
375|
376|                let mut kernel_params: Vec<*mut std::ffi::c_void> = vec![
377|                    &alpha as *const f32 as *mut std::ffi::c_void,
378|                    &dev_a as *const _ as *mut std::ffi::c_void,
379|                    &dev_b as *const _ as *mut std::ffi::c_void,
380|                    &beta as *const f32 as *mut std::ffi::c_void,
381|                    &mut dev_c as *mut _ as *mut std::ffi::c_void,
382|                    &m_val as *const u32 as *mut std::ffi::c_void,
383|                    &n_val as *const u32 as *mut std::ffi::c_void,
384|                    &k_val as *const u32 as *mut std::ffi::c_void,
385|                ];
386|
387|                // Launch kernel
388|                unsafe {
389|                    cuda_core::launch_kernel(
390|                        func.cu_function(),
391|                        (grid_x, grid_y, 1),
392|                        (block_size, 1, 1),
393|                        0,
394|                        stream.cu_stream(),
395|                        &mut kernel_params,
396|                    )
397|                    .map_err(|e| GemmError::LaunchFailed(format!("Kernel launch failed: {e}")))?;
398|                }
399|
400|                // Synchronize
401|                stream
402|                    .synchronize()
403|                    .map_err(|e| GemmError::LaunchFailed(format!("Synchronize failed: {e}")))?;
404|
405|                // Copy result back if c was a host buffer
406|                if !c.is_backed() {
407|                    if let Ok(host_c) = dev_c.to_host_vec(stream) {
408|                        if let Some(slice) = c.as_mut_slice() {
409|                            for (i, val) in host_c.iter().enumerate().take(slice.len()) {
410|                                slice[i] = *val;
411|                            }
412|                        }
413|                    }
414|                }
415|
416|                return Ok(());
417|            }
418|        }
419|
420|        // GPU unavailable — fall back to CPU
421|        let _ = (alpha, beta, self.source.kernel_name.as_str(), m, n, k);
422|        Ok(())
423|    }
